#!/usr/bin/env bash
# run_shard.sh -- the v1.25 acceptance kit (meshsim WORKER11): one shard of a program's windows, generated by a delivery
# writer into scratch space a batch at a time, replayed at once in Stage A and Stage B, the delivery then deleted
# (DECISIONS-v1.25 s2, s7). Only the results are kept. Java 17+; nothing else (the replay controller is prebuilt).
#
#   ./run_shard.sh -p PROGRAM -f FIRST -n COUNT -w 'WRITER' [-b BATCH] [-j JOBS] [-s AB] [-t SCRATCH] OUTDIR
#     -w  the writer command; {out} {first} {count} {program} are substituted. It must write windows FIRST.. of PROGRAM
#         in REPLAY-INPUT-REQUIREMENTS.md's format (manifest.json, PROGRAM/window_NNNNN.*, tables/ optional) into {out}
#     -b  windows per batch (default 128: ~0.7 GB of scratch at 65,536 rows)   -j  JVMs in parallel (default nproc)
#     -s  stages: A, B or AB (default AB)                                      -t  scratch directory (default /tmp)
# Writes OUTDIR/results.csv (one line per window and stage), OUTDIR/batch-*.log, OUTDIR/SUMMARY.txt and VERDICT.txt.
# Exit 0 only if every window of the shard was written and matched in every stage.
set -u
HERE=$(cd "$(dirname "$0")" && pwd)
P=; F=; N=; W=; B=128; J=$(nproc); S=AB; T=/tmp
while getopts p:f:n:w:b:j:s:t: o; do case $o in p) P=$OPTARG;; f) F=$OPTARG;; n) N=$OPTARG;; w) W=$OPTARG;; b) B=$OPTARG;;
  j) J=$OPTARG;; s) S=$OPTARG;; t) T=$OPTARG;; *) sed -n '2,13p' "$0"; exit 2;; esac; done
shift $((OPTIND - 1)); OUT=${1:?usage: run_shard.sh -p PROGRAM -f FIRST -n COUNT -w WRITER OUTDIR}
[ -n "$P" ] && [ -n "$F" ] && [ -n "$N" ] && [ -n "$W" ] || { sed -n '2,13p' "$0"; exit 2; }
mkdir -p "$OUT"; OUT=$(cd "$OUT" && pwd); : > "$OUT/results.csv"
JAVA="java -Xmx1500m -Dreplay.tables=$HERE/tables/replayer -Dreplay.build=$HERE/replay -cp $HERE/meshsim.jar"
SCR=$(mktemp -d "$T/w11-shard.XXXXXX"); trap 'rm -rf "$SCR"' EXIT
T0=$(date +%s); WTOT=0; RTOT=0; GAPS=0
for ((b = F; b < F + N; b += B)); do
  c=$(( F + N - b < B ? F + N - b : B ))
  D="$SCR/batch"; rm -rf "$D"; mkdir -p "$D"
  cmd=${W//\{out\}/$D}; cmd=${cmd//\{first\}/$b}; cmd=${cmd//\{count\}/$c}; cmd=${cmd//\{program\}/$P}
  t1=$(date +%s)
  (cd "$HERE" && eval "$cmd") > "$OUT/batch-$b.log" 2>&1 || { echo "writer failed for windows $b..$((b + c - 1)) (batch-$b.log)"; GAPS=$((GAPS + c)); continue; }
  t2=$(date +%s); WTOT=$((WTOT + t2 - t1))
  for ((k = 0; k < J; k++)); do
    (cd "$HERE" && $JAVA ReplayShard "$D" "$P" "$OUT/part-$b-$k.csv" --stages "$S" --stride "$J" --phase "$k" >> "$OUT/batch-$b.log" 2>&1) &
  done
  wait
  t3=$(date +%s); RTOT=$((RTOT + t3 - t2))
  cat "$OUT"/part-$b-*.csv >> "$OUT/results.csv" 2>/dev/null; rm -f "$OUT"/part-$b-*.csv
  echo "batch $b..$((b + c - 1)): writer $((t2 - t1)) s, replay $((t3 - t2)) s, $(grep -c ',OK,' "$OUT/results.csv") OK lines so far"
  rm -rf "$D"
done
# the verdict: every window of the shard present in every stage, every line OK
python3 - "$OUT" "$P" "$F" "$N" "$S" "$WTOT" "$RTOT" "$(( $(date +%s) - T0 ))" "$J" <<'PY'
import csv, sys
out, prog, f, n, stages, wt, rt, tot, j = sys.argv[1], sys.argv[2], int(sys.argv[3]), int(sys.argv[4]), sys.argv[5], int(sys.argv[6]), int(sys.argv[7]), int(sys.argv[8]), int(sys.argv[9])
rows = list(csv.reader(open(out + "/results.csv")))
seen = {}; bad = []; per = {}
for r in rows:
    if len(r) < 9: bad.append(("?", "malformed line " + ",".join(r))); continue
    st = r[3].split(":")[0]
    if r[4] != "OK": bad.append((r[1], r[3] + " " + r[4] + " " + r[8][:300]))
    else: seen.setdefault(st, set()).add(int(r[1]))
    if r[4] == "OK":
        p = per.setdefault(st, [0, 0, 0]); p[0] += int(r[5]); p[1] += int(r[7]); p[2] += 1
want = set(range(f, f + n)); missing = {st: sorted(want - seen.get(st, set())) for st in stages}
with open(out + "/SUMMARY.txt", "w") as s:
    s.write(f"program {prog}, windows {f}..{f + n - 1} ({n}), stages {stages}, {j} JVMs\n")
    s.write(f"wall {tot} s: writer {wt} s, replay {rt} s\n")
    for st, (rws, ms, k) in sorted(per.items()):
        s.write(f"stage {st}: {k} windows OK, {rws} rows, {ms / 1000:.1f} JVM-s, {rws / max(ms, 1) * 1000:.0f} rows per JVM-second, {ms / max(k, 1) / 1000:.2f} s per window\n")
with open(out + "/VERDICT.txt", "w") as v:
    for st in stages:
        v.write(f"{'ok  ' if not missing[st] else 'FAIL'} stage {st}: {n - len(missing[st])} of {n} windows matched" + (f"; missing {missing[st][:20]}" if missing[st] else "") + "\n")
    for w, m in bad[:50]: v.write(f"FAIL window {w}: {m}\n")
    ok = not bad and all(not m for m in missing.values())
    v.write(("PASS" if ok else "FAIL") + f": {prog} windows {f}..{f + n - 1}\n")
sys.exit(0 if ok else 1)
PY
RC=$?
cat "$OUT/SUMMARY.txt" "$OUT/VERDICT.txt"
exit $RC
